// Auto-generated Chaitanya Mens PG & Hostel official brand logo (PNG base64)
export const LOGO_PNG_BASE64 = '';

let _cachedBytes = null;
export function getLogoPngBytes() {
  if (_cachedBytes) return _cachedBytes;
  if (typeof Buffer !== 'undefined') {
    _cachedBytes = Buffer.from(LOGO_PNG_BASE64, 'base64');
    return _cachedBytes;
  }
  const binary = atob(LOGO_PNG_BASE64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  _cachedBytes = bytes;
  return _cachedBytes;
}
